import{_ as a,o as t,c as n,a2 as r}from"./chunks/framework.CDpkVv68.js";const p=JSON.parse('{"title":"Weapon reach and spacing","description":"","frontmatter":{},"headers":[],"relativePath":"en/game-design/combat/reach-and-spacing.md","filePath":"en/game-design/combat/reach-and-spacing.md"}'),i={name:"en/game-design/combat/reach-and-spacing.md"};function o(s,e,c,l,d,h){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="weapon-reach-and-spacing" tabindex="-1">Weapon reach and spacing <a class="header-anchor" href="#weapon-reach-and-spacing" aria-label="Permalink to &quot;Weapon reach and spacing&quot;">​</a></h1><p><strong>Design status: Proposed.</strong> Numeric examples are prototype hypotheses, not final balance. <strong>Implementation/availability:</strong> not established for these mechanics. <strong>Verification:</strong> documentation review, no playable prototype. <strong>Reviewed:</strong> 2026-10-09, Batch 05.</p><p><a href="/Syrolands-Public/en/guide/combat/reach-and-spacing.html">Player guide</a> · <a href="/Syrolands-Public/en/game-design/combat/overview.html">Combat foundations</a> · <a href="/Syrolands-Public/en/game-design/combat/variable-registry.html">Combat Variable Registry</a></p><h2 id="reach-belongs-to-all-weapons" tabindex="-1">Reach belongs to all weapons <a class="header-anchor" href="#reach-belongs-to-all-weapons" aria-label="Permalink to &quot;Reach belongs to all weapons&quot;">​</a></h2><p>Ranged does not mean only bows. Reach is an action&#39;s physical maximum; minimum/effective range and spatial footprint are distinct. A long weapon may excel at distance and handle poorly up close.</p><table tabindex="0"><thead><tr><th>Illustrative weapon/action</th><th>Candidate tile reach</th><th>Effective-range intention</th></tr></thead><tbody><tr><td>Dagger</td><td>1</td><td>Strong close use; cannot simply hit farther</td></tr><tr><td>Sword</td><td>Usually 1</td><td>Ordinary close engagement</td></tr><tr><td>Spear</td><td>2</td><td>Reach advantage only with matching presentation</td></tr><tr><td>Long spear / pike</td><td>2–3</td><td>Could excel at 3 and be poor at 1</td></tr><tr><td>Large hammer / polearm action</td><td>May affect 2</td><td>Depends on actual action and footprint</td></tr><tr><td>Bow</td><td>Longer, unresolved</td><td>Projectile model with shared accuracy factors</td></tr></tbody></table><p>These are prototype examples, not selected distances or current engine capability. Minimum legal range, sweet-spot effectiveness and maximum reach must not collapse into a single number. Lunge, Sweep and Crushing Arc can modify reach through physically credible action. Athletics or another skill does not magically lengthen equipment; it may unlock/improve such techniques.</p><h2 id="mechanical-and-visible-reach-must-agree" tabindex="-1">Mechanical and visible reach must agree <a class="header-anchor" href="#mechanical-and-visible-reach-must-agree" aria-label="Permalink to &quot;Mechanical and visible reach must agree&quot;">​</a></h2><p>A spear striking at 2–3 tiles must visibly reach its target through the chosen animation/sprite/effect. No invisible-distance melee. This is a presentation requirement alongside server authority, not permission for sprite pixels to decide hits or for animation completion to gate outcomes. If current assets cannot communicate the action, report the feasibility conflict before implementation; do not silently lengthen reach or rewrite the design.</p><p>Orientation, LOS, target movement, collision and body profiles require explicit action rules. Arc/area extent is spatial footprint, not automatically maximum range or guaranteed multiple hits. Per-target contact, area budgets and friendly-fire rules remain unresolved.</p><p><a href="/Syrolands-Public/en/game-design/combat/actions.html#canonical-action-schema">Action schema</a> and <a href="/Syrolands-Public/en/game-design/combat/legacy-and-modern.html#archery-and-ranged-actions">Legacy/Modern ranged rules</a> own execution and projectile timing. No client rendering or network changes are selected.</p><h2 id="batch-06-numeric-test-scope" tabindex="-1">Batch 06 numeric test scope <a class="header-anchor" href="#batch-06-numeric-test-scope" aria-label="Permalink to &quot;Batch 06 numeric test scope&quot;">​</a></h2><p>The <a href="/Syrolands-Public/en/game-design/combat/numeric-prototype.html">three-weapon profile</a> assigns Experimental test values for Longsword, Spear and War Hammer. Its phase, resource, cadence, Flow, martial Familiarity and preparation rules apply only to that future test. Earlier examples remain historical alternatives outside this profile; no final balance, gameplay implementation or spell-number assignment follows.</p>',13)])])}const g=a(i,[["render",o]]);export{p as __pageData,g as default};
